const controls=[];
export function makeChoice(element,options,{node,label,editable=false}={}){const wrap=node('div','vehicle-choice simple-choice'),menu=node('div','choice-menu'),select=element.tagName==='SELECT',display=select?node('button','choice-display'):element,arrow=node('button','choice-trigger','⌄');menu.hidden=true;menu.setAttribute('role','listbox');menu.id='pick-'+(element.name||element.id||controls.length);arrow.type='button';arrow.setAttribute('aria-label','Mostrar opciones de '+label);arrow.addEventListener('pointerdown',e=>e.preventDefault());if(select){display.type='button';element.hidden=true;element.required=false;element.before(wrap);wrap.append(element,display);}else{element.removeAttribute('list');element.readOnly=!editable;element.before(wrap);wrap.append(element);display.setAttribute('aria-label',label);}wrap.append(arrow,menu);display.setAttribute('role','combobox');display.setAttribute('aria-controls',menu.id);display.setAttribute('aria-expanded','false');display.setAttribute('aria-haspopup','listbox');
 const items=options||[...element.options].map(o=>({value:o.value,label:o.textContent}));const normalized=items.map(o=>typeof o==='string'?{value:o,label:o}:o);const close=()=>{menu.hidden=true;display.setAttribute('aria-expanded','false');};const sync=()=>{if(select)display.textContent=normalized.find(o=>o.value===element.value)?.label||'Selecciona una opción';};const show=()=>{document.querySelectorAll('.choice-menu').forEach(m=>{if(m!==menu)m.hidden=true;});menu.replaceChildren();const q=editable?display.value.toLowerCase():'';for(const item of normalized.filter(o=>!q||o.label.toLowerCase().includes(q))){const button=node('button','',item.label);button.type='button';button.setAttribute('role','option');button.setAttribute('aria-selected',String(element.value===item.value));button.addEventListener('pointerdown',e=>e.preventDefault());button.onclick=()=>{element.value=item.value;sync();close();element.dispatchEvent(new Event('input',{bubbles:true}));element.dispatchEvent(new Event('change',{bubbles:true}));};menu.append(button);}if(!menu.children.length)menu.append(node('p','','Puedes escribir el nombre de la ciudad.'));menu.hidden=false;display.setAttribute('aria-expanded','true');};
 arrow.onclick=()=>menu.hidden?show():close();if(select)display.onclick=()=>menu.hidden?show():close();else{display.addEventListener('focus',show);if(editable)display.addEventListener('input',show);else display.addEventListener('click',show);}display.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();show();menu.querySelector('button')?.focus();}if(e.key==='Escape')close();});menu.addEventListener('keydown',e=>{const buttons=[...menu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(e.key==='Escape'){display.focus();close();}});wrap.addEventListener('focusout',()=>queueMicrotask(()=>{if(!wrap.contains(document.activeElement))close();}));const record={wrap,close,sync};controls.push(record);sync();return record;}
document.addEventListener('click',e=>{for(const c of controls)if(!c.wrap.contains(e.target))c.close();for(const menu of document.querySelectorAll('.vehicle-choice:not(.simple-choice) .choice-menu'))if(!menu.closest('.vehicle-choice').contains(e.target))menu.hidden=true;});
